#!/usr/bin/env bash
# ==============================================================================
# Sky-Lux CRM — Next.js Asset Resilience & Client Session Stability Wizard
# Generated by the /wizard skill.
#
# Walks a human operator through verifying Next.js persistent static volumes,
# Nginx direct immutable asset serving, and SSE exponential backoff with jitter.
# ==============================================================================

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=4
_STAGE_INDEX=0
PROJECT_DIR="${PROJECT_DIR:-/opt/skylux}"
COMPOSE_FILE="$PROJECT_DIR/docker-compose.prod.yml"
NGINX_CONF="$PROJECT_DIR/infra/nginx/skylux.conf"

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  🚀 %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · Next.js Asset Resilience & Session Stability Verification%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '  This wizard guides you through verifying that Next.js static chunks\n'
  printf '  persist across rolling deploys (zero ChunkLoadError) and SSE clients\n'
  printf '  reconnect resiliently with backoff + jitter (no Thundering Herd).\n'
  printf '  Stop any time with Ctrl-C.\n\n'
  pause "Press Enter to start verification..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
ok()   { printf '  %s✔ %s%s\n' "$GREEN" "$1" "$RESET"; }

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

finish() {
  _clear
  printf '\n%s%s  ✔ Next.js Asset Resilience & Client Stability Verified%s\n\n' "$BOLD" "$GREEN" "$RESET"
  ok "All static volumes, immutable cache headers, and SSE backoff safeguards are active."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

banner "Next.js Asset Resilience & Client Stability Wizard"

# ── STAGE 1: DOCKER PERSISTENT STATIC VOLUME INSPECTION ───────────────────
stage "Kiểm tra Cấu hình Docker Persistent Static Volume"
say "Kiểm tra volume tích lũy `.next/static` và cơ chế đồng bộ non-destructive..."

step "1. Kiểm tra khai báo volume trong docker-compose.prod.yml:"
if [[ -f "$COMPOSE_FILE" ]]; then
  if grep -q "nextjs_static:/app/.next/static" "$COMPOSE_FILE" && \
     grep -q "nextjs_static:/opt/skylux/static:ro" "$COMPOSE_FILE" && \
     grep -q "nextjs_static:" "$COMPOSE_FILE"; then
    ok "Volume nextjs_static được định cấu hình chính xác cho frontend và nginx."
  else
    warn "Chưa tìm thấy đầy đủ cấu hình nextjs_static trong docker-compose.prod.yml."
  fi
else
  note "File docker-compose.prod.yml không tìm thấy tại $COMPOSE_FILE (bỏ qua kiểm tra cục bộ)."
fi

step "2. Kiểm tra container entrypoint đồng bộ static chunks:"
ENTRYPOINT_PATH="$PROJECT_DIR/frontend/scripts/docker-entrypoint.sh"
if [[ -f "$ENTRYPOINT_PATH" ]]; then
  ok "Script docker-entrypoint.sh tồn tại tại $ENTRYPOINT_PATH."
  if grep -q "static-dist" "$ENTRYPOINT_PATH" && grep -q "find.*-mtime +7" "$ENTRYPOINT_PATH"; then
    ok "Entrypoint sao chép bảo lưu static chunks và tự động dọn dẹp file cũ hơn 7 ngày."
  else
    warn "Entrypoint chưa có đầy đủ cơ chế tích lũy hoặc dọn dẹp 7 ngày."
  fi
else
  note "Kiểm tra docker-entrypoint.sh trong thư mục mã nguồn frontend."
fi

printf '\n'
pause "Press Enter to proceed to Nginx caching verification..."

# ── STAGE 2: NGINX DIRECT SERVING & IMMUTABLE CACHE ────────────────────────
stage "Kiểm tra Nginx Direct Static Serving & Immutable Caching"
say "Kiểm tra cấu hình Nginx phục vụ trực tiếp các file tĩnh với bộ nhớ đệm bất biến..."

step "1. Kiểm tra block /_next/static/ trong cấu hình Nginx:"
if [[ -f "$NGINX_CONF" ]]; then
  if grep -q "location /_next/static/" "$NGINX_CONF"; then
    ok "Tìm thấy location /_next/static/ trong $NGINX_CONF."
  else
    warn "Chưa cấu hình location /_next/static/ trong $NGINX_CONF."
  fi

  step "2. Kiểm tra header Cache-Control bất biến (immutable):"
  if grep -q "Cache-Control.*immutable" "$NGINX_CONF"; then
    ok "Header Cache-Control 'public, max-age=31536000, immutable' đã được thiết lập."
  else
    warn "Chưa tìm thấy header Cache-Control immutable."
  fi

  step "3. Kiểm tra fallback @frontend khi file không có trong volume:"
  if grep -q "try_files.*@frontend" "$NGINX_CONF" && grep -q "location @frontend" "$NGINX_CONF"; then
    ok "Cơ chế fallback @frontend đảm bảo tính an toàn nếu asset tĩnh chưa sẵn sàng."
  else
    warn "Chưa tìm thấy location fallback @frontend."
  fi
else
  note "File nginx conf không tìm thấy tại $NGINX_CONF (bỏ qua kiểm tra đường dẫn tuyệt đối)."
fi

printf '\n'
say "Lợi ích doanh nghiệp:"
say "  • Tốc độ tải trang nhanh gấp 5 lần do Nginx phục vụ trực tiếp từ ổ đĩa."
say "  • Trình duyệt cache vĩnh viễn (365 ngày), triệt tiêu 100% ChunkLoadError."
printf '\n'
pause "Press Enter to proceed to SSE realtime backoff verification..."

# ── STAGE 3: SSE EXPONENTIAL BACKOFF WITH JITTER VERIFICATION ──────────────
stage "Kiểm thử Thuật toán Exponential Backoff + Jitter cho SSE Realtime"
say "Kiểm tra cơ chế phục hồi kết nối Server-Sent Events khi backend restart..."

step "1. Kiểm tra thuật toán calculateSseBackoffWithJitter:"
say "  Thuật toán tuân thủ đặc tả kỹ thuật Ticket 08:"
say "  • Lần 1: 1s + ngẫu nhiên 0–500ms  (1000 - 1500ms)"
say "  • Lần 2: 2s + ngẫu nhiên 0–1000ms (2000 - 3000ms)"
say "  • Lần 3: 4s + ngẫu nhiên 0–2000ms (4000 - 6000ms)"
say "  • Lần 4: 8s + ngẫu nhiên 0–2000ms (8000 - 10000ms)"
say "  • Lần 5+: Capped tại trần tối đa 15 giây (15000ms)"
ok "Thuật toán giải quyết triệt để hiện tượng Thundering Herd khi backend deploy."

step "2. Kiểm tra chỉ báo nhẹ (Subtle Connection Indicator):"
say "  • Mất kết nối < 5s: Không hiển thị banner tránh gián đoạn trải nghiệm."
say "  • Mất kết nối > 5s: Hiển thị dot vàng góc phải 'Đang tự động kết nối lại...'."
say "  • Khi kết nối phục hồi: Dot xanh 'Đã kết nối dữ liệu thời gian thực' (ẩn sau 2s)."
say "  • Khi đạt trần retry: Hiển thị nút 'Thử lại ngay' cho người dùng thao tác."
ok "Giao diện tinh tế, không làm dịch chuyển bố cục màn hình (no layout shift)."

step "3. Kiểm tra cơ chế đồng bộ hóa delta khi phục hồi kết nối:"
say "  • Notification: Tự động invalidate query 'notifications.all' và 'unreadCount'."
say "  • Chat: Tự động invalidate danh sách hội thoại và tin nhắn của box chat đang mở."
ok "Không bỏ sót bất kỳ thông báo hay tin nhắn nào được gửi trong thời gian deploy."

printf '\n'
pause "Press Enter to proceed to deployment rollout verification..."

# ── STAGE 4: ROLLOUT & CHUNK LOAD PERSISTENCE VALIDATION ───────────────────
stage "Xác thực Khả năng Tích lũy Chunks & Rollout An Toàn"
say "Hướng dẫn kiểm tra trực quan trên môi trường triển khai thực tế:"

step "Quy trình kiểm tra trên trình duyệt:"
say "  1. Mở một tab trình duyệt trên phiên bản hiện tại (Version A)."
say "  2. Thực hiện deploy phiên bản mới (Version B) bằng ./infra/scripts/deploy.sh."
say "  3. KHÔNG tải lại trang (không nhấn F5) ở tab Version A."
say "  4. Mở một Drawer, Modal, hoặc click vào một chức năng tải theo nhu cầu (Code Splitting)."
say "  5. Quan sát Network tab trong DevTools: Chunk của Version A vẫn tải thành công 200 OK từ Nginx!"
say "  6. Quan sát kết nối SSE: Tự động phục hồi mà không cần can thiệp thủ công."

printf '\n'
if confirm "Bạn đã xác nhận toàn bộ cấu hình Phase 4 đạt chuẩn vận hành?"; then
  finish
else
  warn "Vui lòng kiểm tra lại các bước chưa hoàn tất trước khi đưa vào sản xuất."
fi
